"""Generates supabase/migrations/..._syllabus.sql and src/lib/syllabus.ts from one list.
Chapters follow the Andhra Pradesh Board of Intermediate Education (BIEAP) structure; students should verify against their current syllabus."""
import json, pathlib
ROOT = pathlib.Path(__file__).resolve().parent.parent
S = {
 "mathematics": [
  (1, "1A", ["Functions", "Mathematical Induction", "Matrices", "Addition of Vectors", "Product of Vectors", "Trigonometric Ratios up to Transformations", "Trigonometric Equations", "Inverse Trigonometric Functions", "Hyperbolic Functions", "Properties of Triangles"]),
  (1, "1B", ["Locus", "Transformation of Axes", "The Straight Line", "Pair of Straight Lines", "Three Dimensional Coordinates", "Direction Cosines and Direction Ratios", "The Plane", "Limits and Continuity", "Differentiation", "Errors and Approximations", "Tangents and Normals", "Rate Measure", "Maxima and Minima"]),
  (2, "2A", ["Complex Numbers", "De Moivre's Theorem", "Quadratic Expressions", "Theory of Equations", "Permutations and Combinations", "Binomial Theorem", "Partial Fractions", "Measures of Dispersion", "Probability", "Random Variables and Probability Distributions"]),
  (2, "2B", ["Circle", "System of Circles", "Parabola", "Ellipse", "Hyperbola", "Integration", "Definite Integrals", "Differential Equations"]),
 ],
 "physics": [
  (1, "I", ["Physical World", "Units and Measurements", "Motion in a Straight Line", "Motion in a Plane", "Laws of Motion", "Work, Energy and Power", "Systems of Particles and Rotational Motion", "Oscillations", "Gravitation", "Mechanical Properties of Solids", "Mechanical Properties of Fluids", "Thermal Properties of Matter", "Thermodynamics", "Kinetic Theory"]),
  (2, "II", ["Waves", "Ray Optics and Optical Instruments", "Wave Optics", "Electric Charges and Fields", "Electrostatic Potential and Capacitance", "Current Electricity", "Moving Charges and Magnetism", "Magnetism and Matter", "Electromagnetic Induction", "Alternating Current", "Electromagnetic Waves", "Dual Nature of Radiation and Matter", "Atoms", "Nuclei", "Semiconductor Electronics", "Communication Systems"]),
 ],
 "chemistry": [
  (1, "I", ["Atomic Structure", "Classification of Elements and Periodicity in Properties", "Chemical Bonding and Molecular Structure", "States of Matter: Gases and Liquids", "Stoichiometry", "Thermodynamics", "Chemical Equilibrium and Acids-Bases", "Hydrogen and its Compounds", "The s-Block Elements", "p-Block Elements: Group 13", "p-Block Elements: Group 14", "Environmental Chemistry", "Organic Chemistry: Basic Principles and Techniques", "Hydrocarbons"]),
  (2, "II", ["Solid State", "Solutions", "Electrochemistry and Chemical Kinetics", "Surface Chemistry", "General Principles of Metallurgy", "p-Block Elements: Groups 15 to 18", "d and f Block Elements and Coordination Compounds", "Polymers", "Biomolecules", "Chemistry in Everyday Life", "Haloalkanes and Haloarenes", "Alcohols, Phenols and Ethers", "Aldehydes, Ketones and Carboxylic Acids", "Organic Compounds Containing Nitrogen"]),
 ],
}
pre = {"mathematics": "m", "physics": "p", "chemistry": "c"}
rows = []
for subj, papers in S.items():
    for year, paper, chs in papers:
        for i, t in enumerate(chs, 1):
            rows.append({"id": f"{pre[subj]}{paper.lower()}-{i:02d}", "subject": subj, "year": year, "paper": paper, "position": i, "title": t})
q = lambda s: "'" + s.replace("'", "''") + "'"
sql = ["-- Syllabus reference data (generated by scripts/syllabus.py). Based on the AP BIEAP Intermediate structure.",
       "insert into public.chapters (id, subject, year, paper, position, title) values"]
sql.append(",\n".join(f"  ({q(r['id'])}, {q(r['subject'])}, {r['year']}, {q(r['paper'])}, {r['position']}, {q(r['title'])})" for r in rows))
sql[-1] += "\non conflict (id) do update set subject = excluded.subject, year = excluded.year, paper = excluded.paper, position = excluded.position, title = excluded.title;\n"
(ROOT / "supabase/migrations/20261109000002_syllabus.sql").write_text("\n".join(sql))
ts = "// Generated by scripts/syllabus.py — keep in sync with the chapters table.\nexport type Chapter = { id: string; subject: Subject; year: 1 | 2; paper: string; position: number; title: string };\nexport type Subject = \"mathematics\" | \"physics\" | \"chemistry\";\nexport const CHAPTERS: Chapter[] = " + json.dumps(rows, indent=1) + ";\n"
(ROOT / "src/lib/syllabus.ts").write_text(ts)
print(len(rows), "chapters")
